def order(api, customer_id, *items):
    return api.orders.handle_create({"customer_id": customer_id,
                                     "items": [{"sku": s, "quantity": q} for s, q in items]})


def test_unknown_customer_is_404(shop):
    response = shop.insights.handle_order_history("nobody")
    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_customer_with_no_orders_gets_empty_list(shop):
    response = shop.insights.handle_order_history("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "orders": []}


def test_orders_are_newest_first_and_include_cancelled(shop):
    first = order(shop, "c1", ("PEN", 1)).body["order_id"]
    second = order(shop, "c1", ("BOOK", 1)).body["order_id"]
    shop.orders.handle_cancel(first)
    response = shop.insights.handle_order_history("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "orders": [
        {"order_id": second, "status": "placed", "total_cents": 2_500},
        {"order_id": first, "status": "cancelled", "total_cents": 300},
    ]}


def test_other_customers_orders_are_excluded(shop):
    order(shop, "c2", ("PEN", 1))
    mine = order(shop, "c1", ("PEN", 2)).body["order_id"]
    orders = shop.insights.handle_order_history("c1").body["orders"]
    assert [o["order_id"] for o in orders] == [mine]


def test_totals_include_discount_and_match_order_summary(shop):
    standard = order(shop, "c1", ("BOOK", 5)).body["order_id"]   # 12_500, 10% off
    gold = order(shop, "c2", ("LAMP", 2)).body["order_id"]       # 12_000, 15% off
    small = order(shop, "c1", ("PEN", 3)).body["order_id"]       # 900, no discount

    orders = shop.insights.handle_order_history("c1").body["orders"]
    by_id = {o["order_id"]: o["total_cents"] for o in orders}
    assert by_id[standard] == 11_250
    assert by_id[small] == 900
    assert by_id[standard] == shop.orders.handle_get(standard).body["total_cents"]
    assert by_id[small] == shop.orders.handle_get(small).body["total_cents"]

    gold_orders = shop.insights.handle_order_history("c2").body["orders"]
    assert gold_orders == [{"order_id": gold, "status": "placed", "total_cents": 10_200}]
    assert gold_orders[0]["total_cents"] == shop.orders.handle_get(gold).body["total_cents"]

