from __future__ import annotations

from typing import Any

from orders.application.errors import CustomerNotFound
from orders.application.order_service import OrderService
from orders.controllers.http import InvalidRequest, Response, bad_request, not_found, require_positive_int


class CustomerInsightsController:
    def __init__(self, service: OrderService) -> None:
        self._service = service

    def handle_order_history(self, customer_id: str) -> Response:
        try:
            summaries = self._service.order_history(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        orders: list[dict[str, Any]] = [
            {"order_id": s.order.order_id, "status": s.order.status, "total_cents": s.total_cents}
            for s in summaries
        ]
        return Response(200, {"customer_id": customer_id, "orders": orders})

    def handle_lifetime_value(self, customer_id: str) -> Response:
        try:
            order_count, total_cents = self._service.lifetime_value(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        return Response(200, {"customer_id": customer_id, "order_count": order_count,
                              "lifetime_value_cents": total_cents})

def order(api, customer_id, *items):
    return api.orders.handle_create({"customer_id": customer_id,
                                     "items": [{"sku": s, "quantity": q} for s, q in items]})


def test_unknown_customer_is_404(shop):
    response = shop.insights.handle_order_history("nobody")
    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_customer_with_no_orders_gets_empty_list(shop):
    response = shop.insights.handle_order_history("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "orders": []}


def test_orders_are_newest_first_and_include_cancelled(shop):
    first = order(shop, "c1", ("PEN", 1)).body["order_id"]
    second = order(shop, "c1", ("BOOK", 1)).body["order_id"]
    shop.orders.handle_cancel(first)
    response = shop.insights.handle_order_history("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "orders": [
        {"order_id": second, "status": "placed", "total_cents": 2_500},
        {"order_id": first, "status": "cancelled", "total_cents": 300},
    ]}


def test_lifetime_value_unknown_customer_is_404(shop):
    response = shop.insights.handle_lifetime_value("nobody")
    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_lifetime_value_of_customer_with_no_orders_is_zero(shop):
    response = shop.insights.handle_lifetime_value("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "order_count": 0, "lifetime_value_cents": 0}


def test_lifetime_value_excludes_cancelled_orders(shop):
    order(shop, "c1", ("BOOK", 5))             # 12_500 less 10% = 11_250
    order(shop, "c1", ("PEN", 3))              # 900
    cancelled = order(shop, "c1", ("PEN", 1)).body["order_id"]  # 300, cancelled
    shop.orders.handle_cancel(cancelled)
    response = shop.insights.handle_lifetime_value("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "order_count": 2, "lifetime_value_cents": 12_150}


def test_lifetime_value_matches_sum_of_order_history_totals(shop):
    order(shop, "c2", ("LAMP", 2))             # 12_000 less 15% = 10_200
    order(shop, "c2", ("BOOK", 1))             # 2_500
    response = shop.insights.handle_lifetime_value("c2")
    history = shop.insights.handle_order_history("c2").body["orders"]
    live = [o["total_cents"] for o in history if o["status"] != "cancelled"]
    assert response.body["order_count"] == len(live) == 2
    assert response.body["lifetime_value_cents"] == sum(live) == 12_700


def test_other_customers_orders_are_excluded(shop):
    order(shop, "c2", ("PEN", 1))
    mine = order(shop, "c1", ("PEN", 2)).body["order_id"]
    orders = shop.insights.handle_order_history("c1").body["orders"]
    assert [o["order_id"] for o in orders] == [mine]


def test_totals_include_discount_and_match_order_summary(shop):
    standard = order(shop, "c1", ("BOOK", 5)).body["order_id"]   # 12_500, 10% off
    gold = order(shop, "c2", ("LAMP", 2)).body["order_id"]       # 12_000, 15% off
    small = order(shop, "c1", ("PEN", 3)).body["order_id"]       # 900, no discount

    orders = shop.insights.handle_order_history("c1").body["orders"]
    by_id = {o["order_id"]: o["total_cents"] for o in orders}
    assert by_id[standard] == 11_250
    assert by_id[small] == 900
    assert by_id[standard] == shop.orders.handle_get(standard).body["total_cents"]
    assert by_id[small] == shop.orders.handle_get(small).body["total_cents"]

    gold_orders = shop.insights.handle_order_history("c2").body["orders"]
    assert gold_orders == [{"order_id": gold, "status": "placed", "total_cents": 10_200}]
    assert gold_orders[0]["total_cents"] == shop.orders.handle_get(gold).body["total_cents"]

